def meeting_card(key):
    m=NEXT_MEETINGS[key]
    h=f'<section class="meeting-card" aria-label="Next {escape(m["label"])} meeting"><span class="eyebrow">Next {escape(m["label"])} meeting</span><h2>{escape(m["title"])}</h2>'
    if not (m['start'] and m['end'] and m['location']):
        return h+'<p>Location: Bierce 154. The next date and time will be posted when confirmed.</p></section>'
    start=datetime.fromisoformat(m['start']).replace(tzinfo=ZoneInfo('America/New_York'))
    end=datetime.fromisoformat(m['end']).replace(tzinfo=ZoneInfo('America/New_York'))
    if end<=start: raise ValueError('Meeting end must be after start')
    fmt=lambda d:d.astimezone(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    params={'action':'TEMPLATE','text':m['title'],'dates':fmt(start)+'/'+fmt(end),'stz':'America/New_York','etz':'America/New_York','location':m['location'],'details':'UNA-USA at The University of Akron'}
    url='https://calendar.google.com/calendar/render?'+urlencode(params)
    date=start.strftime('%A, %B %-d, %Y')
    times=start.strftime('%-I:%M %p')+'–'+end.strftime('%-I:%M %p')
    return h+f'<p><time datetime="{m["start"]}">{date}, {times}</time><br><strong>Location:</strong> {escape(m["location"])}</p><a class="button navy" href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a></section>'

