def note(title,msg,action=''):return f'<div class="empty"><span class="eyebrow">{title}</span><p>{msg}</p>{action}</div>'
def calendar_link(title,day,start_hour,end_hour,start_minute=0,end_minute=0,location=None,month=10):
    tz=ZoneInfo('America/New_York')
    start=datetime(2026,month,day,start_hour,start_minute,tzinfo=tz)
    end=datetime(2026,month,day,end_hour,end_minute,tzinfo=tz)
    fmt=lambda d:d.astimezone(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    params={'action':'TEMPLATE','text':title,'dates':fmt(start)+'/'+fmt(end),
            'stz':'America/New_York','etz':'America/New_York',
            'details':'UNA-USA at The University of Akron. '+('Suit and tie. See the event page for details.' if location==UN_DAY_LOCATION else 'Bierce 154.' if location==BIERCE_LOCATION else 'Check the chapter calendar for room updates.')}
    if location: params['location']=location
    return 'https://calendar.google.com/calendar/render?'+urlencode(params)

