def october_calendar():
    special={5:[('Chapter meeting · 6–7 PM','chapter')],14:[('Events · 4:45–5:45 PM','events')],19:[('Chapter meeting · 6–7 PM','chapter')],26:[('United Nations Day','feature')],28:[('Events · 4:45–5:45 PM','events')]}
    weekday_names='Mon Tue Wed Thu Fri Sat Sun'.split()
    grid='<div class="cal-grid" aria-label="October 2026 calendar">'+''.join(f'<div class="cal-weekday">{w}</div>' for w in weekday_names)
    for week in calendar.monthcalendar(2026,10):
        for day in week:
            if not day:
                grid+='<div class="cal-day empty" aria-hidden="true"></div>'
                continue
            entries=list(special.get(day,[]))
            if date(2026,10,day).weekday()==2:
                entries.extend([('Model UN · 3–5 PM','mun'),('Research · 5–6 PM','research')])
            label=date(2026,10,day).strftime('%A, %B %-d')
            grid+=f'<div class="cal-day{" has-event" if entries else ""}"><span class="cal-date" aria-label="{label}">{day}</span>'
            grid+=''.join(
                f'<a class="cal-event {kind}" href="{("/events/un-day-2026/" if kind=="feature" else f"#event-2026-10-{day:02d}"+(f"-{kind}" if kind in ("mun","research") else ""))}"'
                f'{(" target=\"_blank\" rel=\"noopener noreferrer\"" if kind=="feature" else "")}>{escape(title)}</a>'
                for title,kind in entries
            )
            grid+='</div>'
    grid+='</div>'
    entries=[(5,'General meeting','chapter','6–7 PM · Bierce 154.'),
             (7,'Model UN practice','mun','3–5 PM · Bierce 154.'),
             (7,'Research meeting','research','5–6 PM · Bierce 154.'),
             (14,'Model UN practice','mun','3–5 PM · Bierce 154.'),
             (14,'Events team meeting','events','4:45–5:45 PM · Bierce 154.'),
             (14,'Research meeting','research','5–6 PM · Bierce 154.'),
             (19,'General meeting with a Bliss Institute speaker','chapter','6–7 PM · Bierce 154.'),
             (21,'Model UN practice','mun','3–5 PM · Bierce 154.'),
             (21,'Research meeting','research','5–6 PM · Bierce 154.'),
             (26,'United Nations Day','feature','5–7:30 PM · The University of Akron School of Law, Room 180.'),
             (28,'Model UN practice','mun','3–5 PM · Bierce 154.'),
             (28,'Events team meeting','events','4:45–5:45 PM · Bierce 154.'),
             (28,'Research meeting','research','5–6 PM · Bierce 154.')]
    agenda='<div class="calendar-agenda">'
    previous_day=None
    for day,title,kind,details in entries:
        when=date(2026,10,day)
        event_id=f'event-2026-10-{day:02d}'+(f'-{kind}' if kind in ('mun','research') else '')
        category={'mun':'Model UN','research':'Research','events':'Events team'}.get(kind,'Chapter event')
        if day!=previous_day:
            if previous_day is not None: agenda+='</div></article>'
            agenda+=f'<article class="agenda-item" id="event-2026-10-{day:02d}"><div class="agenda-date"><span>{when.strftime("%b")}</span><b>{day}</b></div><div class="agenda-items"><span class="eyebrow">{when.strftime("%A")} · '+('Akron Law Room 180' if kind=='feature' else 'Bierce 154')+'</span>'
        inner_id=f' id="{event_id}"' if kind in ('mun','research') else ''
        agenda+=f'<section class="agenda-subitem {kind}"{inner_id}><h3>{escape(title)}</h3><p>{escape(details)}</p>'
        if kind=='mun':
            url=calendar_link('UNA-USA Akron Model UN practice',day,15,17,location=BIERCE_LOCATION)
            agenda+=f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a>'
        if kind=='research':
            url=calendar_link('UNA-USA Akron research meeting',day,17,18,location=BIERCE_LOCATION)
            agenda+=f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a>'
        if kind=='events':
            url=events_calendar_url(day)
            agenda+=f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a>'
        if kind=='chapter':
            url=calendar_link('UNA-USA Akron general meeting'+(' · Bliss Institute speaker' if day==19 else ''),day,18,19,location=BIERCE_LOCATION)
            agenda+=f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a>'
        if kind=='feature':
            agenda+='<a href="/events/un-day-2026/" target="_blank" rel="noopener noreferrer">View the UN Day program <span aria-hidden="true">↗</span></a>'
            agenda+=f' <a href="{escape(UN_DAY_CALENDAR_URL,quote=True)}" target="_blank" rel="noopener noreferrer">Add to Google Calendar <span aria-hidden="true">↗</span></a>'
        agenda+='</section>'
        previous_day=day
    if previous_day is not None: agenda+='</div></article>'
    return grid+agenda+'</div>'
