def mun_resource_sections(levels):
    sections=[]
    for level,title,intro,items in levels:
        cards=''.join(
            f'<a class="resource-card" href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">'
            f'<span class="resource-source">{escape(source)}</span><h3>{escape(name)}</h3>'
            f'<p>{escape(description)}</p><span class="resource-open">Open resource <span aria-hidden="true">↗</span></span></a>'
            for name,description,source,url in items
        )
        section_id='learn' if level=='Beginner' else 'research' if level=='Advanced' else 'resource-intermediate'
        sections.append(f'<section class="resource-level" id="{section_id}" aria-labelledby="resource-{level.lower()}">'
                        f'<span class="eyebrow">{escape(level)}</span><h2 id="resource-{level.lower()}">{escape(title)}</h2>'
                        f'<p class="resource-intro">{escape(intro)}</p><div class="resource-grid">{cards}</div></section>')
    return ''.join(sections)
