def resource_card_grid(items):
    return '<div class="resource-grid">'+''.join(
        f'<a class="resource-card" href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">'
        f'<span class="resource-source">{escape(source)}</span><h3>{escape(name)}</h3>'
        f'<p>{escape(description)}</p><span class="resource-open">Open resource <span aria-hidden="true">↗</span></span></a>'
        for name,description,source,url in items
    )+'</div>'
def mun_video_section():
    videos=''.join(
        f'<li><a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">'
        f'<span class="video-number">{number:02d}</span><span><strong>{escape(name)}</strong>'
        f'<small>{escape(source)} · {escape(skill)}</small></span><span class="video-arrow" aria-hidden="true">↗</span></a></li>'
        for number,(name,source,skill,url) in enumerate(MUN_VIDEOS,1)
    )
    further=[
        ('MSUMUN How to MUN playlist','Continue through procedure, caucuses, and resolutions.','MSUMUN','https://www.youtube.com/playlist?list=PLepDF0MESt_4ymh9GONZQNp_IBL88umu1'),
        ('Best Delegate Training Video Library','Explore additional lessons on speeches, research, debate, and strategy.','Best Delegate','https://muninstitute.com/pages/model-united-nations-video-gallery'),
    ]
    return '<section class="resource-level" id="watch" aria-labelledby="watch-title"><span class="eyebrow">Watch</span>' \
        '<h2 id="watch-title">Beginner video library</h2><p class="resource-intro">Follow these eleven lessons in order, from your first committee through country research.</p>' \
        f'<ol class="video-list">{videos}</ol><h3>Keep learning</h3>{resource_card_grid(further)}</section>'
def mun_extra_section(section_id,title,intro,items):
    return f'<section class="resource-level" id="{section_id}" aria-labelledby="{section_id}-title">' \
        f'<span class="eyebrow">{escape(section_id.title())}</span><h2 id="{section_id}-title">{escape(title)}</h2>' \
        f'<p class="resource-intro">{escape(intro)}</p>{resource_card_grid(items)}</section>'
def mun_resource_nav():
    labels=[('Learn','Start with the essentials'),('Watch','Follow 11 short lessons'),('Practice','Try a simulation'),('Play','Build geography and awareness'),('Research','Use primary sources')]
    return '<nav class="resource-navigation" aria-label="Training resource sections">'+''.join(
        f'<a href="#{name.lower()}"><strong>{name}</strong><span>{description}</span></a>'
        for name,description in labels
    )+'</nav>'
